import React, { useRef } from 'react';

const SignToText = () => {
  const samplesRef = useRef([]);

  const generateDemoVector = (type) => {
    const vec = new Array(42).fill(0);
    const base = {
      HELLO: 0.22,
      'I LOVE YOU': 0.2,
      YES: 0.04,
      NO: 0.08,
      I: 0.1,
      LIVE: 0.15,
      IN: 0.12,
      INDIA: 0.18,
      'ARE YOU': 0.2,
      OKAY: 0.1
    };
    const scale = base[type] || 0.1;

    for (let p = 0; p < 21; p++) {
      let magnitude = 0.06;
      if ([4, 8, 12, 16, 20].includes(p)) magnitude = scale + (Math.random() - 0.5) * 0.02;
      const angle = (p / 21) * Math.PI * 2;
      const x = Math.cos(angle) * magnitude + (Math.random() - 0.5) * 0.01;
      const y = Math.sin(angle) * magnitude + (Math.random() - 0.5) * 0.01;
      vec[p * 2] = x;
      vec[p * 2 + 1] = y;
    }

    let xs = [];
    for (let i = 0; i < 42; i += 2) xs.push(vec[i]);
    const cx = xs.reduce((s, v) => s + v, 0) / xs.length;
    let maxd = 0;
    for (let i = 0; i < 42; i += 2) {
      const dx = vec[i] - cx;
      const dy = vec[i + 1];
      maxd = Math.max(maxd, Math.hypot(dx, dy));
    }
    const inv = 1 / (maxd || 1);
    for (let i = 0; i < 42; i += 2) {
      vec[i] = (vec[i] - cx) * inv;
      vec[i + 1] = vec[i + 1] * inv;
    }
    return vec;
  };

  const loadDemoSamples = () => {
    const labels = ['HELLO', 'I LOVE YOU', 'YES', 'NO', 'I', 'LIVE', 'IN', 'INDIA', 'ARE YOU', 'OKAY'];
    const perLabel = 12;
    const demo = [];

    for (const lbl of labels) {
      for (let i = 0; i < perLabel; i++) {
        const baseVec = generateDemoVector(lbl);
        // Add tiny noise
        const noisy = baseVec.map(v => v + (Math.random() - 0.5) * 0.02);
        demo.push({ label: lbl, vector: noisy });
      }
    }

    samplesRef.current = demo;
    alert('Loaded demo samples for HELLO, I LOVE YOU, YES, NO, I, LIVE, IN, INDIA, ARE YOU, OKAY (' + demo.length + ' total)');
  };

  return (
    <div>
      <h1>Sign Language to Text Demo</h1>
      <button onClick={loadDemoSamples}>Load Demo Samples</button>
      <div>
        <h2>Samples Loaded:</h2>
        <ul>
          {samplesRef.current.map((sample, index) => (
            <li key={index}>{sample.label}: {JSON.stringify(sample.vector)}</li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default SignToText;
